package com.littlemorning.alarm;

import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.os.*;
import android.provider.Settings;
import android.net.Uri;
import android.speech.tts.TextToSpeech;
import android.graphics.Typeface;
import android.view.*;
import android.widget.*;
import java.text.SimpleDateFormat;
import java.util.*;

public final class MainActivity extends StyledActivity {
    private final Handler handler=new Handler(Looper.getMainLooper());
    private final ArrayDeque<String> history=new ArrayDeque<>();
    private String page="home",module="weather",chosenPreset="fast";
    static boolean visible;
    private boolean foreground,opened,pendingDemo,refreshCalendar;
    private TextView nextLabel;
    private LinearLayout root,body;
    private final Runnable poll=new Runnable(){public void run(){if(!foreground)return;updateHome();if("ringing".equals(Config.prefs(MainActivity.this).getString("phase","idle"))&&!opened){opened=true;startActivity(new Intent(MainActivity.this,AlarmActivity.class));}handler.postDelayed(this,500);}};
    @Override public void onCreate(Bundle saved){super.onCreate(saved);
        if(!AlarmService.active&&Arrays.asList("ringing","speaking","paused").contains(p().getString("phase","idle")))Config.state(this,"idle","上次播放已结束");
        if(saved!=null){page=saved.getString("page","home");module=saved.getString("module","weather");pendingDemo=saved.getBoolean("pendingDemo");chosenPreset=saved.getString("chosenPreset","fast");}
        else if(!p().getBoolean("onboarded_v2",false)){if(p().contains("hour")||p().contains("agendaText"))p().edit().putBoolean("onboarded_v2",true).apply();else page="welcome-time";}
        render();
    }
    private android.content.SharedPreferences p(){return Config.prefs(this);}
    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    private void go(String to){if(!to.equals(page))history.push(page);page=to;render();}
    private void back(){if(page.startsWith("welcome")){if(page.equals("welcome-plan")){page="welcome-time";render();}else super.onBackPressed();return;}page=history.isEmpty()?"home":history.pop();render();}
    @Override public void onBackPressed(){if(page.equals("home"))super.onBackPressed();else back();}
    @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putString("page",page);b.putString("module",module);b.putBoolean("pendingDemo",pendingDemo);b.putString("chosenPreset",chosenPreset);}
    private void shell(String title,String right,Runnable action){root=Ui.mount(this);Ui.header(this,root,title,page.equals("home")||page.startsWith("welcome")?null:()->back(),right,action);body=Ui.scroll(root);}
    private void footer(String title,Runnable action){Ui.space(root,12);root.addView(Ui.button(this,title,true,action));}
    private void render(){nextLabel=null;switch(page){case "welcome-time":onboardingTime();break;case "welcome-plan":presets(true);break;case "time":timeEditor();break;case "routine":routine();break;case "module":moduleEditor();break;case "settings":settings();break;case "permissions":permissions();break;case "sound":sound();break;case "test":testAlarm();break;case "presets":presets(false);break;default:page="home";home();}}
    private TextView clock(String time){TextView t=Ui.text(this,time,104,R.color.ink);t.setTypeface(Typeface.create("sans-serif-light",0));t.setLetterSpacing(-.055f);t.setSingleLine(true);t.setAutoSizeTextTypeUniformWithConfiguration(64,104,2,android.util.TypedValue.COMPLEX_UNIT_SP);t.setMinHeight(Ui.dp(this,132));return t;}
    private String time(){return String.format(Locale.ROOT,"%02d:%02d",p().getInt("hour",7),p().getInt("minute",30));}
    private String days(){int mask=p().getInt("days",62);if(mask==62)return "周一至周五";if(mask==127)return "每天";String[] labels={"日","一","二","三","四","五","六"};List<String> out=new ArrayList<>();for(int i=0;i<7;i++)if((mask&(1<<i))!=0)out.add(labels[i]);return "每周 "+String.join("、",out);}
    private void home(){shell("早一点","设置",()->go("settings"));
        Ui.space(body,40);body.addView(Ui.text(this,"下一次起床",14,R.color.muted));Ui.space(body,8);
        TextView t=clock(time());t.setContentDescription("编辑起床时间，当前 "+time());t.setOnClickListener(v->go("time"));t.setFocusable(true);Ui.ripple(t);body.addView(t,new LinearLayout.LayoutParams(-1,-2));Ui.space(body,12);
        LinearLayout alarm=Ui.row(this);LinearLayout copy=Ui.column(this);copy.addView(Ui.text(this,days(),16,R.color.ink));Ui.space(copy,8);nextLabel=Ui.text(this,"",14,R.color.muted);if(p().getBoolean("enabled",false)&&!ready()){nextLabel.setMinHeight(Ui.dp(this,48));nextLabel.setOnClickListener(v->{pendingDemo=false;go("permissions");});}copy.addView(nextLabel);Ui.weight(alarm,copy);Switch enabled=new Switch(this);enabled.setContentDescription("启用起床闹钟");enabled.setChecked(p().getBoolean("enabled",false));enabled.setMinHeight(Ui.dp(this,48));alarm.addView(enabled);enabled.setOnCheckedChangeListener((v,value)->{if(value&&!ready()){enabled.setChecked(false);pendingDemo=false;go("permissions");return;}p().edit().putBoolean("enabled",value).apply();try{Config.nextDaily(this);}catch(Exception e){p().edit().putBoolean("enabled",false).apply();enabled.setChecked(false);toast("闹钟未启用，请完成权限设置");}updateHome();});body.addView(alarm);Ui.space(body,32);Ui.line(body);Ui.space(body,8);
        LinearLayout routine=Ui.row(this);routine.setMinimumHeight(Ui.dp(this,64));String summary=Config.summary(this);TextView preview=Ui.text(this,"起床后："+summary,16,R.color.muted);preview.setSingleLine(true);preview.setEllipsize(android.text.TextUtils.TruncateAt.END);Ui.weight(routine,preview);TextView arrow=Ui.text(this,"›",20,R.color.muted);arrow.setPadding(Ui.dp(this,12),0,0,0);routine.addView(arrow);routine.setContentDescription("晨间播报，"+summary+"，点按编辑");Ui.ripple(routine);routine.setFocusable(true);routine.setOnClickListener(v->go("routine"));body.addView(routine);updateHome();
    }
    private void preview(){if(activeCount()==0){toast("请先开启一项播报内容");return;}Config.start(this,Config.SPEAK);startActivity(new Intent(this,AlarmActivity.class));}
    private int activeCount(){int count=0;for(String key:Config.order(this))if(Config.enabled(this,key))count++;return count;}
    private boolean ready(){return Config.exact(this)&&getSystemService(NotificationManager.class).areNotificationsEnabled();}
    private void updateHome(){if(nextLabel==null||!page.equals("home"))return;long test=p().getLong("nextTest",0);if(test>System.currentTimeMillis()){Ui.setText(nextLabel,p().getString("nextKind","test").equals("snooze")?"贪睡中 · "+Math.max(1,(test-System.currentTimeMillis()+59999)/60000)+" 分钟后再响":"体验将在 "+Math.max(1,(test-System.currentTimeMillis()+999)/1000)+" 秒后响铃");return;}if(!p().getBoolean("enabled",false)){Ui.setText(nextLabel,"未开启");return;}if(!ready()){Ui.setText(nextLabel,"待授权 · 点此设置");return;}long next=p().getLong("nextDaily",0);Ui.setText(nextLabel,next>0?new SimpleDateFormat("M 月 d 日 EEEE",Locale.CHINA).format(new Date(next))+" · 已安排":"打开时间设置，保存后安排闹钟。");}
    private void testAlarm(){shell("体验响铃",null,null);Ui.title(body,"试一次，再放心开启。","先保持前台体验，再安排一次并锁屏测试。");Ui.note(body,"响铃后长按起床，会自动开始播报。选择贪睡则 5 分钟后再次响铃。");Ui.space(body,24);body.addView(Ui.quiet(this,"取消体验 / 贪睡",()->{Config.cancelTest(this);Config.start(this,Config.STOP);toast("已取消本次体验，日常闹钟不变");}));footer("10 秒后体验起床",()->{if(!ready()){pendingDemo=true;go("permissions");}else scheduleDemo();});}
    private void scheduleDemo(){try{Config.schedule(this,System.currentTimeMillis()+10000,false);Config.state(this,"idle","10 秒后响铃");pendingDemo=false;history.clear();page="home";render();toast("已安排 10 秒后响铃，现在可以锁屏");}catch(Exception e){toast("未能安排闹钟，请检查准时响铃权限");}}
    private TimePicker picker(LinearLayout target){TimePicker t=(TimePicker)getLayoutInflater().inflate(R.layout.time_picker,target,false);t.setIs24HourView(true);t.setHour(p().getInt("hour",7));t.setMinute(p().getInt("minute",30));stylePicker(t);target.addView(t,new LinearLayout.LayoutParams(-1,-2));return t;}
    private void stylePicker(View view){if(view instanceof EditText){EditText e=(EditText)view;e.setTextSize(32);e.setTextColor(Ui.color(this,R.color.ink));e.setTypeface(Typeface.create("sans-serif-light",0));}if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)stylePicker(((ViewGroup)view).getChildAt(i));}
    private void onboardingTime(){shell("早一点",null,null);body.addView(Ui.text(this,"01 / 02",12,R.color.muted));Ui.space(body,24);Ui.title(body,"明天，几点醒来？","先选一个适合你的时间。其余的，慢慢来。");TimePicker t=picker(body);footer("下一步",()->{p().edit().putInt("hour",t.getHour()).putInt("minute",t.getMinute()).apply();page="welcome-plan";render();});}
    private void presets(boolean onboarding){shell(onboarding?"早一点":"选择晨间方案",null,null);if(onboarding){body.addView(Ui.text(this,"02 / 02",12,R.color.muted));Ui.space(body,24);}Ui.title(body,"想怎样开始今天？","选一个方案就好，之后随时可以调整。");
        Ui.item(body,"极速通勤","天气示例 → 今日日程\n短一些，把重要的事先听完。",chosenPreset.equals("fast")?"●":"○",()->{chosenPreset="fast";render();});
        Ui.item(body,"轻柔唤醒","晨间旋律 → 天气示例 → 提醒\n留 20 秒，慢慢醒过来。",chosenPreset.equals("soft")?"●":"○",()->{chosenPreset="soft";render();});Ui.space(body,24);body.addView(Ui.text(this,"天气目前为示例，日程默认手动填写。本地旋律不需要联网。",14,R.color.muted));
        footer(onboarding?"用这个方案开始":"使用这个方案",()->{Config.preset(this,chosenPreset);p().edit().putBoolean("onboarded_v2",true).apply();history.clear();page="home";render();});}
    private void timeEditor(){shell("起床时间",null,null);TimePicker t=picker(body);Ui.section(body,"每周重复");final int[] mask={p().getInt("days",62)};String[] labels={"日","一","二","三","四","五","六"};for(int group=0;group<2;group++){LinearLayout row=Ui.row(this);for(int j=0;j<4;j++){int ix=group*4+j;if(ix>=7){Ui.weight(row,new TextView(this));break;}final int day=(ix+1)%7;Button b=Ui.button(this,labels[day],(mask[0]&(1<<day))!=0,()->{});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(Ui.dp(this,2),Ui.dp(this,4),Ui.dp(this,2),Ui.dp(this,4));row.addView(b,lp);b.setContentDescription("星期"+labels[day]);b.setSelected((mask[0]&(1<<day))!=0);b.setOnClickListener(v->{mask[0]^=1<<day;boolean selected=(mask[0]&(1<<day))!=0;b.setSelected(selected);b.setTextColor(Ui.color(this,selected?R.color.on_accent:R.color.ink));b.setBackground(Ui.shape(this,Ui.color(this,selected?R.color.accent:R.color.surface),16));});}body.addView(row);}
        footer("保存时间",()->{if(mask[0]==0){toast("至少选择一个重复日");return;}p().edit().putInt("hour",t.getHour()).putInt("minute",t.getMinute()).putInt("days",mask[0]).apply();try{Config.nextDaily(this);}catch(Exception e){p().edit().putBoolean("enabled",false).apply();toast("偏好已保存，闹钟需要补齐权限后开启");}back();});}
    private void routine(){shell("晨间播报",null,null);body.addView(Ui.text(this,"长按把手排序，点内容进入设置。",14,R.color.muted));Ui.space(body,20);
        for(String key:Config.order(this)){
            LinearLayout row=Ui.row(this);row.setMinimumHeight(Ui.dp(this,80));row.setPadding(0,Ui.dp(this,12),0,Ui.dp(this,12));LinearLayout copy=Ui.column(this);copy.addView(Ui.text(this,Config.title(key),17,R.color.ink));Ui.space(copy,7);copy.addView(Ui.text(this,moduleSummary(key),12,R.color.muted));copy.setPadding(0,Ui.dp(this,4),Ui.dp(this,4),Ui.dp(this,4));copy.setFocusable(true);Ui.ripple(copy);copy.setOnClickListener(v->{module=key;go("module");});Ui.weight(row,copy);
            Switch toggle=new Switch(this);toggle.setContentDescription("启用"+Config.title(key));toggle.setChecked(Config.enabled(this,key));toggle.setMinHeight(Ui.dp(this,48));toggle.setOnCheckedChangeListener((v,checked)->p().edit().putBoolean(key,checked).putString("preset","custom").apply());row.addView(toggle);
            Button drag=Ui.quiet(this,"≡",()->{});drag.setTextSize(24);drag.setContentDescription("排序"+Config.title(key)+"，长按拖动或点击选择上移下移");row.addView(drag,new LinearLayout.LayoutParams(Ui.dp(this,48),-2));drag.setOnLongClickListener(v->{v.startDragAndDrop(ClipData.newPlainText("module",key),new View.DragShadowBuilder(row),key,0);return true;});drag.setOnClickListener(v->{PopupMenu menu=new PopupMenu(this,drag);menu.getMenu().add("上移").setOnMenuItemClickListener(i->{move(key,-1);return true;});menu.getMenu().add("下移").setOnMenuItemClickListener(i->{move(key,1);return true;});menu.show();});
            row.setOnDragListener((v,event)->{Object local=event.getLocalState();if(!(local instanceof String)||!PlanOrder.KEYS.contains(local))return false;switch(event.getAction()){case DragEvent.ACTION_DRAG_ENTERED:row.setBackgroundColor(Ui.color(this,R.color.surface));break;case DragEvent.ACTION_DRAG_EXITED:case DragEvent.ACTION_DRAG_ENDED:row.setBackgroundColor(android.graphics.Color.TRANSPARENT);break;case DragEvent.ACTION_DROP:List<String> list=Config.order(this);int target=list.indexOf(key);list.remove((String)local);list.add(target,(String)local);p().edit().putString("order",PlanOrder.join(list)).putString("preset","custom").apply();render();break;}return true;});body.addView(row);Ui.line(body);
        }
        Ui.space(body,24);body.addView(Ui.text(this,"没有内容或未授权的项目会跳过，其他内容继续播放。",14,R.color.muted));footer("试听我的早晨",()->preview());}
    private void move(String key,int delta){List<String> order=Config.order(this);int from=order.indexOf(key),to=from+delta;if(to<0||to>=order.size()){toast(delta<0?"已经是第一项":"已经是最后一项");return;}Collections.swap(order,from,to);p().edit().putString("order",PlanOrder.join(order)).putString("preset","custom").apply();render();}
    private String moduleSummary(String key){switch(key){case "weather":return p().getString("city","上海")+" · 演示天气";case "music":return "20 秒 · 本地原创旋律";case "agenda":return p().getString("agendaSource","manual").equals("calendar")?"系统日历 · 只读今天":"手动日程";default:return "留给自己的几句话";}}
    private void moduleEditor(){shell(Config.title(module),null,null);switch(module){
        case "weather":Ui.title(body,"选择所在城市","本版使用固定天气示例，不会把它当成真实预报。");EditText city=Ui.field(body,"城市",p().getString("city","上海"),false);Ui.space(body,24);Ui.note(body,"目前手动选择城市，无需定位权限。接入真实天气后，再按需请求定位。");footer("保存城市",()->{String value=city.getText().toString().trim();if(value.isEmpty()){city.setError("请输入城市");return;}p().edit().putString("city",value).apply();back();});break;
        case "music":Ui.title(body,"给醒来留 20 秒。","一段随 App 保存的原创合成旋律。");Ui.note(body,"离线可播放，不连接第三方歌单或音乐账号。你可以在声音设置里调整音量。");Ui.item(body,"声音设置","调整播放音量与语速","›",()->go("sound"));footer("完成",()->back());break;
        case "agenda":agendaEditor();break;
        default:Ui.title(body,"有什么想提醒自己？","每次醒来都会读出这些内容，直到你修改。");EditText reminder=Ui.field(body,"例如：带好钥匙，记得吃早餐",p().getString("reminderText","出门前记得带钥匙，给自己留一点吃早餐的时间。"),true);footer("保存提醒",()->{p().edit().putString("reminderText",reminder.getText().toString()).apply();back();});
    }}
    private void agendaEditor(){Ui.title(body,"只听今天重要的事。","可以手动填写，也可以只读系统日历。");RadioGroup source=new RadioGroup(this);RadioButton manual=new RadioButton(this),calendar=new RadioButton(this);manual.setText("手动填写，每次重复使用");calendar.setText("读取系统日历，当天自动更新");manual.setId(View.generateViewId());calendar.setId(View.generateViewId());manual.setMinHeight(Ui.dp(this,52));calendar.setMinHeight(Ui.dp(this,52));source.addView(manual);source.addView(calendar);source.check(p().getString("agendaSource","manual").equals("calendar")?calendar.getId():manual.getId());body.addView(source);Ui.space(body,16);EditText text=Ui.field(body,"例如：10 点项目会议",p().getString("agendaText","10 点项目会议"),true);
        boolean allowed=checkSelfPermission("android.permission.READ_CALENDAR")==PackageManager.PERMISSION_GRANTED;Ui.space(body,20);Ui.note(body,allowed?"日历读取已允许。仅在选择系统日历时读取今天前 5 项，不新增、不修改事件。":"尚未授权日历。选择系统日历后，未授权或当天没日程会自动跳过这一项。");body.addView(Ui.quiet(this,allowed?"管理日历权限":"连接系统日历",()->{p().edit().putString("agendaText",text.getText().toString()).putString("agendaSource","calendar").apply();if(allowed||p().getBoolean("askedCalendar",false)&&!shouldShowRequestPermissionRationale("android.permission.READ_CALENDAR")){refreshCalendar=true;open(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())));}else{p().edit().putBoolean("askedCalendar",true).apply();requestPermissions(new String[]{"android.permission.READ_CALENDAR"},20);}}));
        footer("保存日程",()->{p().edit().putString("agendaText",text.getText().toString()).putString("agendaSource",source.getCheckedRadioButtonId()==calendar.getId()?"calendar":"manual").apply();back();});}
    private void settings(){shell("设置",null,null);Ui.title(body,"设置你的偏好",null);Ui.item(body,"外观",themeLabel(),"›",()->theme());Ui.item(body,"声音","音量与语速","›",()->go("sound"));Ui.item(body,"闹钟与权限",ready()?"通知与准时响铃已允许":"按需完成手机设置","›",()->{pendingDemo=false;go("permissions");});Ui.item(body,"体验响铃","10 秒后响铃，可测试锁屏","›",()->go("test"));Ui.item(body,"重新选择晨间方案","保留起床时间，替换播报搭配","›",()->go("presets"));Ui.space(body,32);body.addView(Ui.text(this,"早一点 0.2.1\n天气为示例，内容保存在此设备。",12,R.color.muted));}
    private String themeLabel(){String theme=p().getString("theme","system");return theme.equals("night")?"夜间":theme.equals("day")?"日间":"跟随系统";}
    private void theme(){String[] keys={"system","day","night"};int selected=Arrays.asList(keys).indexOf(p().getString("theme","system"));new AlertDialog.Builder(this).setTitle("外观").setSingleChoiceItems(new String[]{"跟随系统","日间","夜间"},selected,(d,i)->{p().edit().putString("theme",keys[i]).apply();d.dismiss();recreate();}).setNegativeButton("取消",null).show();}
    private void sound(){shell("声音",null,null);Ui.title(body,"用舒服的声音开始。","播放音量仍受系统闹钟音量影响。");Ui.section(body,"播放音量");SeekBar volume=new SeekBar(this);volume.setMax(90);volume.setProgress(p().getInt("volume",60)-10);body.addView(volume);Ui.section(body,"语速 · 舒缓到轻快");SeekBar rate=new SeekBar(this);rate.setMax(40);rate.setProgress(p().getInt("rate",100)-80);body.addView(rate);Ui.space(body,24);Ui.item(body,"中文语音","下载或启用手机的中文朗读语音","›",()->voiceSettings());footer("保存声音",()->{p().edit().putInt("volume",volume.getProgress()+10).putInt("rate",rate.getProgress()+80).apply();back();});}
    private void permissions(){shell("闹钟与权限",null,null);Ui.title(body,pendingDemo?"先让体验准时发生。":"让下一次起床准时。","只在需要时授权，随时可以在系统中修改。");NotificationManager nm=getSystemService(NotificationManager.class);
        Ui.item(body,"通知",nm.areNotificationsEnabled()?"已允许 · 响铃时可从通知控制":"显示闹钟与播放操作","设置  ›",()->{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},9);else open(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()));});
        Ui.item(body,"准时响铃",Config.exact(this)?"已允许 · 按设定时间触发":"需要系统的闹钟和提醒权限","设置  ›",()->{if(Build.VERSION.SDK_INT>=31)open(new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName())));else toast("当前系统无需单独申请");});
        Ui.item(body,"锁屏显示",Build.VERSION.SDK_INT<34||nm.canUseFullScreenIntent()?"可显示 · 实际行为仍由手机系统决定":"未允许时，可点开闹钟通知进入","设置  ›",()->{if(Build.VERSION.SDK_INT>=34)open(new Intent(Settings.ACTION_MANAGE_APP_USE_FULL_SCREEN_INTENT,Uri.parse("package:"+getPackageName())));else open(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()));});
        Ui.space(body,24);Ui.note(body,"若锁屏后未响铃，请检查系统闹钟音量及电池后台限制。首次只需完成通知和准时响铃；锁屏显示用于直接弹出界面。");footer(pendingDemo?"权限允许后，体验 10 秒响铃":"完成",()->{if(pendingDemo){if(ready())scheduleDemo();else toast("请先允许通知和准时响铃");}else back();});}
    private void open(Intent intent){try{startActivity(intent);}catch(Exception e){toast("请到手机的应用设置中调整该项");}}
    private void voiceSettings(){try{startActivity(new Intent("com.android.settings.TTS_SETTINGS"));}catch(Exception e){open(new Intent(TextToSpeech.Engine.ACTION_INSTALL_TTS_DATA));}}
    @Override public void onRequestPermissionsResult(int request,String[] names,int[] grants){super.onRequestPermissionsResult(request,names,grants);if(request==20||page.equals("permissions"))render();}
    @Override protected void onResume(){super.onResume();visible=true;foreground=true;opened=false;if(page.equals("permissions")||refreshCalendar){refreshCalendar=false;render();}handler.removeCallbacks(poll);handler.post(poll);}
    @Override protected void onPause(){visible=false;foreground=false;handler.removeCallbacks(poll);super.onPause();}
}
